/// A class's row: its name, its base (Infection's DWARF, the first where
/// it has two; none for a root or a class the DWARF lacks), its
/// constructor (the lowest of its overloads) and vtable by volume.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ClassInfo {
    pub class: GameClass,
    pub name: &'static str,
    pub base: Option<GameClass>,
    pub constructor: [Option<u32>; 4],
    pub vtable: [Option<u32>; 4],
}

/// How many classes there are.
pub const COUNT: usize = 310;

/// Every class's row, by its discriminant (one line a row).
#[rustfmt::skip]
