impl GameClass {
    /// Its row.
    pub const fn info(self) -> &'static ClassInfo {
        &CLASSES[self as usize]
    }

    /// Its name in the symbols and the DWARF.
    pub const fn name(self) -> &'static str {
        self.info().name
    }

    /// Its base class.
    pub const fn base(self) -> Option<GameClass> {
        self.info().base
    }

    /// Its constructor's address on `v`.
    pub const fn constructor(self, v: Volume) -> Option<u32> {
        self.info().constructor[v as usize]
    }

    /// Its vtable's address on `v`.
    pub const fn vtable(self, v: Volume) -> Option<u32> {
        self.info().vtable[v as usize]
    }

    /// Every class, in order.
    pub fn all() -> impl Iterator<Item = GameClass> {
        CLASSES.iter().map(|c| c.class)
    }
}

